create table if not exists public.expenses (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, amount numeric(12,2) not null check(amount>0), category text not null, expense_date date not null default current_date, payment text not null default 'UPI', note text default '', created_at timestamptz not null default now());
create table if not exists public.settings (user_id uuid primary key references auth.users(id) on delete cascade, monthly_income numeric(12,2) not null default 0, monthly_budget numeric(12,2) not null default 50000, bank_balance numeric(12,2) not null default 0, name text default 'Dinesh', language text default 'en', updated_at timestamptz not null default now());
create table if not exists public.goals (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, target numeric(12,2) not null default 0, saved numeric(12,2) not null default 0, created_at timestamptz not null default now());
create table if not exists public.loans (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, emi numeric(12,2) not null default 0, balance numeric(12,2) not null default 0, created_at timestamptz not null default now());
create table if not exists public.recurring (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, amount numeric(12,2) not null default 0, day_of_month int not null default 1 check(day_of_month between 1 and 31), created_at timestamptz not null default now());
create table if not exists public.fuel_logs (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, liters numeric(10,2) not null default 0, km numeric(10,2) not null default 0, amount numeric(12,2) not null default 0, log_date date not null default current_date, created_at timestamptz not null default now());

do $$ declare t text; begin foreach t in array array['expenses','settings','goals','loans','recurring','fuel_logs'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy if not exists "expenses own" on public.expenses for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy if not exists "settings own" on public.settings for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy if not exists "goals own" on public.goals for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy if not exists "loans own" on public.loans for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy if not exists "recurring own" on public.recurring for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy if not exists "fuel own" on public.fuel_logs for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
grant select,insert,update,delete on public.expenses,public.settings,public.goals,public.loans,public.recurring,public.fuel_logs to authenticated;
